function go(p){state.page=p;save();render()}
function head(title,sub,actions=''){return '<div class="page-heading"><div><div class="eyebrow">'+({authority:'DELHI OPERATIONS',family:'FAMILY PORTAL',driver:'COLLECTION CREW',processor:'CIRCULAR ECONOMY'}[state.role])+'</div><h1>'+title+'</h1><p>'+sub+'</p></div><div class="heading-actions">'+actions+'</div></div>'}
function stat(label,value,change,icon,up=true){return '<div class="stat-card"><div class="stat-top"><span>'+label+'</span><span class="stat-icon">'+icon+'</span></div><div class="stat-value">'+value+'</div><div class="stat-meta"><span class="trend '+(up?'':'down')+'">'+change.split('|')[0]+'</span><span>'+change.split('|')[1]+'</span></div></div>'}
function pill(s){let cls=['Collected','Improving','Verified','Excellent'].includes(s)?'':['Missed','Needs focus'].includes(s)?'bad':['On route','Watch'].includes(s)?'warn':'neutral';return '<span class="status-pill '+cls+'">'+esc(s)+'</span>'}
function mapBlock(id='map-overview',large=false){return '<div class="map-wrap '+(large?'map-large':'')+'" id="'+id+'"><div class="map-legend"><span class="legend-item"><i class="legend-dot" style="background:#48a46a"></i> On track</span><span class="legend-item"><i class="legend-dot" style="background:#e4a54b"></i> Watch</span><span class="legend-item"><i class="legend-dot" style="background:#d56759"></i> Needs focus</span></div></div>'}
function areaTable(rows=AREAS){return '<div class="table-scroll"><table class="data-table"><thead><tr><th>Ward / sector</th><th>Households</th><th>Segregation</th><th>Contamination</th><th>7d trend</th><th>Signal</th></tr></thead><tbody>'+rows.map(a=>'<tr><td><b>'+a.name+'</b><br><small class="muted">'+a.ward+'</small></td><td>'+fmt(a.families)+'</td><td><span class="score-pill">'+a.score+'%</span></td><td>'+a.contam+'%</td><td><span class="'+(a.trend>=0?'trend':'trend down')+'">'+(a.trend>0?'+':'')+a.trend+'%</span></td><td>'+pill(a.status)+'</td></tr>').join('')+'</tbody></table></div>'}
function householdTable(list){return '<div class="table-scroll"><table class="data-table"><thead><tr><th>Household</th><th>Area / ward</th><th>Today’s waste</th><th>Score</th><th>Coins</th><th>Pickup</th><th></th></tr></thead><tbody>'+list.map(f=>'<tr><td><div class="family-cell"><span class="mini-avatar">'+initials(f.name)+'</span><span><b>'+f.name+'</b><small>'+f.id+' · '+f.members+' members</small></span></div></td><td>'+f.area+'<br><small class="muted">'+area(f.area).ward+'</small></td><td>'+(f.today.wet+f.today.dry+f.today.special).toFixed(1)+' kg</td><td><span class="score-pill">'+f.score+'</span></td><td>◈ '+f.coins+'</td><td>'+pill(f.status)+'</td><td><button class="text-link" data-action="family-detail" data-id="'+f.id+'">View</button></td></tr>').join('')+'</tbody></table></div>'}
function overview(){return head('Good morning, Operations','A live view of Delhi’s waste-to-value network · Sunday, 04 October 2026','<select class="select" data-action="period"><option value="7">Last 7 days</option><option value="30">Last 30 days</option></select><button class="btn" data-action="export">↓ Export report</button>')+'<div class="stats-grid">'+stat('Registered households','12,840','↑ 8.2%|vs. last month','♧')+stat('Collections today','1,148','↑ 12.4%|vs. daily average','♻')+stat('Waste recovered','18.6 t','↑ 6.8%|this week','↗')+stat('Segregation quality',avg()+'%','↑ 3.1%|vs. last week','◉')+'</div><div class="overview-grid"><section class="panel map-panel"><div class="panel-head"><div><div class="panel-title">Delhi collection map</div><div class="panel-sub">Ward-level segregation health · Live field activity</div></div><button class="text-link" data-page="map">Explore map ↗</button></div>'+mapBlock()+'</section><section class="panel"><div class="panel-head"><div><div class="panel-title">Area health</div><div class="panel-sub">Lowest segregation score · focus first</div></div><button class="text-link" data-page="performance">All areas</button></div><div class="area-list">'+[...AREAS].sort((a,b)=>a.score-b.score).slice(0,5).map((a,i)=>'<div class="area-row"><span class="area-rank">0'+(i+1)+'</span><span><b>'+a.name+'</b><small>'+a.contam+'% contamination · '+fmt(a.families)+' homes</small><span class="bar"><i style="width:'+a.score+'%"></i></span></span><span class="area-score">'+a.score+'%<small class="'+(a.trend>=0?'trend':'trend down')+'">'+(a.trend>0?'+':'')+a.trend+'% this wk</small></span></div>').join('')+'</div></section></div><section class="panel table-panel" style="margin-bottom:15px"><div class="panel-head"><div><div class="panel-title">Live collection activity</div><div class="panel-sub">Household handovers across today’s routes</div></div><div class="table-tools"><input class="search" placeholder="Search family or ID…" data-filter="families"><button class="btn" data-page="families">All households ↗</button></div></div>'+householdTable(state.families.slice(0,5))+'</section><div class="lower-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Waste stream today</div><div class="panel-sub">Verified household collections · by category</div></div><span class="status-pill">Live</span></div><div class="waste-bars"><div class="waste-line"><span class="category-label"><i class="cat-dot"></i>Wet</span><span class="bar"><i style="width:73%"></i></span><strong>8.42 t</strong></div><div class="waste-line"><span class="category-label"><i class="cat-dot" style="background:#85b6cb"></i>Dry</span><span class="bar"><i style="width:48%"></i></span><strong>5.16 t</strong></div><div class="waste-line"><span class="category-label"><i class="cat-dot" style="background:#d6a667"></i>Special</span><span class="bar"><i style="width:15%"></i></span><strong>1.05 t</strong></div></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Circular outcome</div><div class="panel-sub">Verified material destination · this month</div></div><button class="text-link" data-page="processing">Open 3R ledger</button></div><div class="flow"><div class="flow-box"><b>62%</b><small>Recycled · 412 t</small></div><div class="flow-box"><b>18%</b><small>Reused · 120 t</small></div><div class="flow-box"><b>12%</b><small>Recovered · 80 t</small></div><div class="flow-box"><b>8%</b><small>Landfill · 53 t</small></div></div></section></div>'}
function mapPage(){return head('Ward & sector map','Delhi, India · Collection coverage, segregation quality & field attention','<select class="select" data-action="sector-filter"><option>All sectors</option>'+AREAS.map(a=>'<option>'+a.name+'</option>').join('')+'</select>')+'<div class="map-full-grid"><section class="panel map-panel">'+mapBlock('map-large',true)+'</section><aside class="map-side"><section class="panel"><div class="panel-head"><div><div class="panel-title">Map filters</div><div class="panel-sub">Showing live area performance</div></div></div><div class="filter-box"><label>Municipal zone<select><option>All Delhi zones</option><option>South-West</option><option>North-West</option><option>South</option><option>East</option><option>Central</option></select></label><label>Show metric<select><option>Segregation score</option><option>Contamination level</option><option>Collection coverage</option></select></label></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Area status</div><div class="panel-sub">Select a marker for ward detail</div></div></div><div class="map-key"><div class="key-line"><i class="key-dot" style="background:#48a46a"></i>On track · 88%+ segregation</div><div class="key-line"><i class="key-dot" style="background:#e4a54b"></i>Watch · 78–87%</div><div class="key-line"><i class="key-dot" style="background:#d56759"></i>Needs focus · under 78%</div></div></section><section class="panel"><div class="panel-title">City coverage</div><div class="waste-bars"><div class="waste-line"><span>Households</span><span class="bar"><i style="width:72%"></i></span><strong>12.8k</strong></div><div class="waste-line"><span>Wards</span><span class="bar"><i style="width:61%"></i></span><strong>42 / 70</strong></div><div class="waste-line"><span>Routes</span><span class="bar"><i style="width:83%"></i></span><strong>186</strong></div></div></section></aside></div><section class="panel table-panel" style="margin-top:14px"><div class="panel-head"><div><div class="panel-title">Ward performance register</div><div class="panel-sub">Sector-level performance signals, updated from verified collections</div></div></div>'+areaTable(state.sector==='All sectors'?AREAS:AREAS.filter(a=>a.name===state.sector))+'</section>'}
function familiesPage(){return head('Household directory','Family IDs, registered addresses, personalized QR codes & live collection status','<input class="search" placeholder="Search household, QR ID, area…" data-filter="directory"><button class="btn btn-primary" data-action="add-household">＋ Register household</button>')+'<div class="stats-grid">'+stat('Registered','12,840','↑ 8.2%|this month','♧')+stat('Active this week','11,962','93.2%|of households','◉')+stat('Pickups today','1,102','↑ 4.6%|vs. yesterday','♻')+stat('Need follow-up','47','↓ 12|this week','⚑',false)+'</div><section class="panel"><div class="panel-head"><div><div class="panel-title">Registered families</div><div class="panel-sub">Unique QR codes link the family profile, address and verified pickups</div></div><div class="table-tools"><select class="select" data-action="family-area-filter"><option>All areas</option>'+AREAS.map(a=>'<option>'+a.name+'</option>').join('')+'</select><button class="btn" data-action="export">↓ Export CSV</button></div></div><div class="directory-grid" style="padding:0 15px 16px">'+state.families.map(f=>'<article class="family-card"><div class="family-card-top"><span class="mini-avatar">'+initials(f.name)+'</span><span><b>'+f.name+'</b><small>'+f.id+' · '+f.members+' members</small></span><img class="qr-thumb" src="'+qr(f,100)+'" alt="QR '+f.id+'" data-action="show-qr" data-id="'+f.id+'"></div><div class="family-card-metrics"><span><b>'+f.score+'%</b><small>Clean score</small></span><span><b>◈ '+f.coins+'</b><small>Clean coins</small></span><span><b>♨ '+f.streak+'d</b><small>Streak</small></span></div><div class="family-card-foot"><span>'+f.area+'</span><button data-action="family-detail" data-id="'+f.id+'">Open profile ↗</button></div></article>').join('')+'</div></section>'}
function performance(){return head('Area performance','Find where contamination is rising and target the next segregation drive','<select class="select"><option>Last 7 days</option><option>Last 30 days</option></select><button class="btn" data-action="export">↓ Export insights</button>')+'<div class="stats-grid">'+stat('City segregation',avg()+'%','↑ 3.1%|this week','◉')+stat('Avg contamination','7.8%','↓ 1.4%|this week','⚖',false)+stat('Top performing area','Dwarka · 94%','↑ 2.4%|quality score','⌖')+stat('Priority wards','2 areas','↓ 1|vs. last week','⚑',false)+'</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Segregation & contamination trend</div><div class="panel-sub">City score · daily verified handovers</div></div><span class="status-pill">+3.1% this week</span></div><div class="chart-wrap"><canvas id="performance-chart"></canvas></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Focus recommendation</div><div class="panel-sub">Score, contamination & recent direction</div></div></div>'+[...AREAS].sort((a,b)=>a.score-b.score).slice(0,3).map(a=>'<div class="area-row"><span class="area-rank">⚑</span><span><b>'+a.name+'</b><small>'+a.contam+'% contamination · '+Math.abs(a.trend)+'% '+(a.trend<0?'decline':'improvement')+'</small></span><button class="text-link" data-action="focus-area" data-area="'+a.name+'">Plan</button></div>').join('')+'</section></div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Street → society → ward scorecard</div><div class="panel-sub">Families, segregation, contamination and week-over-week direction</div></div></div>'+areaTable()+'</section>'}
const processorBase=[['PR-DEL-4081','04 Oct 2026','GreenLoop Materials','Dry recyclables','1,240 kg','1,108 kg','92 kg','40 kg'],['PR-DEL-4076','04 Oct 2026','Swasth Compost Co.','Wet organics','2,850 kg','2,590 kg','—','260 kg'],['PR-DEL-4062','03 Oct 2026','ReThread Works','Textile','420 kg','—','386 kg','34 kg'],['PR-DEL-4055','03 Oct 2026','E-Waste Saathi','E-waste','186 kg','173 kg','—','13 kg']];
function processing(){let extra=state.events.filter(e=>e.type==='processor').map(e=>[e.id,e.date,e.processor,e.material,e.received,e.recycled,e.reused,e.reject]);return head('3R processing ledger','Verified chain of custody from household collection to final material outcome','<button class="btn btn-primary" data-action="add-processor">＋ Record processing batch</button>')+'<div class="stats-grid">'+stat('Collected this month','665 t','↑ 9.3%|vs. last month','♻')+stat('Recycled','412 t','62%|of collected','↗')+stat('Reused','120 t','18%|of collected','↻')+stat('Landfill diversion','92%','↑ 4.2%|this quarter','◉')+'</div><section class="panel" style="margin-bottom:14px"><div class="panel-head"><div><div class="panel-title">Material outcome</div><div class="panel-sub">Collection → verified processor receipt → final outcome</div></div><span class="status-pill">Chain verified</span></div><div class="flow"><div class="flow-box"><b>665 t</b><small>Total collected</small></div><div class="flow-box"><b>412 t</b><small>Recycled · 62%</small></div><div class="flow-box"><b>120 t</b><small>Reused · 18%</small></div><div class="flow-box"><b>80 t</b><small>Recovered · 12%</small></div></div></section><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Processor receipts</div><div class="panel-sub">Registered 3R dealer digital receipts</div></div><button class="btn" data-action="export">↓ Export ledger</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Receipt / date</th><th>Processor</th><th>Material</th><th>Received</th><th>Recycled</th><th>Reused / recovered</th><th>Reject</th><th>Verification</th></tr></thead><tbody>'+[...extra,...processorBase].map(r=>'<tr>'+r.slice(0,7).map((x,i)=>'<td>'+(i===0?'<b>'+x+'</b><br><small class="muted">'+r[1]+'</small>':x)+'</td>').join('')+'<td>'+pill('Verified')+'</td></tr>').join('')+'</tbody></table></div></section>'}
function collectionLog(){let all=[...state.collections,...state.families.filter(f=>f.status==='Collected').map(f=>({family:f.name,id:f.id,area:f.area,total:(f.today.wet+f.today.dry+f.today.special).toFixed(1),score:f.score,driver:'Rajesh K.',date:'Today, 08:42 AM',points:18}))];return head('Collection log','Every verified household handover, category weight & points settlement','<button class="btn" data-action="export">↓ Download log</button>')+'<div class="stats-grid">'+stat('Verified today',all.length,'Live|handover records','✓')+stat('Weight checked','6.0 kg','± 0.15 kg|allowed tolerance','⚖')+stat('Points issued','2,846','Today|to households','◈')+stat('Exceptions','3','Needs|review','⚑',false)+'</div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Verified handovers</div><div class="panel-sub">Family QR → driver scale → category-weight record → Clean coins</div></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Household</th><th>Ward</th><th>Weight</th><th>Score</th><th>Driver</th><th>Time</th><th>Points</th><th>Status</th></tr></thead><tbody>'+all.map(c=>'<tr><td><b>'+esc(c.family)+'</b><br><small class="muted">'+c.id+'</small></td><td>'+c.area+'</td><td>'+c.total+' kg</td><td>'+c.score+'%</td><td>'+c.driver+'</td><td>'+c.date+'</td><td>◈ '+c.points+'</td><td>'+pill('Verified')+'</td></tr>').join('')+'</tbody></table></div></section>'}
function alerts(){return head('Focus areas','Prioritized field actions to improve segregation and reduce contamination','<button class="btn btn-primary" data-action="campaign">＋ Create awareness drive</button>')+'<div class="notice" style="margin-bottom:14px"><b>Recommended:</b> Door-to-door segregation coaching in Saket and Karol Bagh this week. Both show falling quality and above 11% contamination.</div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Areas requiring intervention</div><div class="panel-sub">Sorted by lowest score and negative trend</div></div></div>'+areaTable(AREAS.filter(a=>a.score<80||a.trend<0).sort((a,b)=>a.score-b.score))+'</section>'}
function familyHome(){let f=fam();return head('Namaste, '+esc(f.name.split(' ')[0])+' family','Your household impact, collection schedule & Clean coins','<select class="select" data-action="select-family">'+state.families.map(x=>'<option value="'+x.id+'" '+(x.id===f.id?'selected':'')+'>'+x.name+' · '+x.id+'</option>').join('')+'</select>')+'<div class="detail-grid"><aside class="profile-card"><div class="profile-avatar">'+initials(f.name)+'</div><h2>'+f.name+'</h2><p>'+f.id+' · '+f.members+' registered members</p><img class="qr-code" src="'+qr(f,220)+'" alt="Customized household QR"><div class="qr-id">Your collection QR</div><button class="btn btn-soft" style="margin-top:9px" data-action="show-qr" data-id="'+f.id+'">View / download QR</button><div class="profile-facts"><div class="fact"><span>Home address</span><b>'+f.address+'</b></div><div class="fact"><span>Collection slot</span><b>Daily · 8:00–10:00 AM</b></div><div class="fact"><span>Assigned route</span><b>'+f.route+' · '+f.area+'</b></div><div class="fact"><span>Next collection</span><b>Tomorrow · 8:30 AM</b></div></div><div class="members-block"><div class="panel-title">Registered members · '+f.members+'</div>'+['Aarav','Ananya','Kabir','Meera','Ishaan','Riya'].slice(0,f.members).map((n,i)=>'<div class="member-row"><span class="mini-avatar">'+(i+1)+'</span><span><b>'+n+' '+f.name.split(' ')[0]+'</b><small>'+(i===0?'Primary contact':'Household member')+'</small></span></div>').join('')+'</div></aside><div class="detail-main"><section class="score-hero"><div><div class="eyebrow" style="color:#c1e58a">YOUR CLEAN SCORE</div><h2>Small habits. Real impact.</h2><p>Score reflects segregation, contamination & consistency.</p></div><div class="score-number">'+f.score+'<small> / 100</small></div></section><div class="family-kpis"><div class="mini-kpi"><small>Clean coins</small><b>◈ '+fmt(f.coins)+'</b></div><div class="mini-kpi"><small>Current streak</small><b>♨ '+f.streak+' days</b></div><div class="mini-kpi"><small>Lifetime pickups</small><b>'+Math.max(36,f.streak*3)+'</b></div><div class="mini-kpi"><small>Area rank</small><b>#'+(state.families.slice().sort((a,b)=>b.score-a.score).findIndex(x=>x.id===f.id)+1)+' / '+state.families.length+'</b></div></div><section class="panel"><div class="panel-head"><div><div class="panel-title">Today’s collection</div><div class="panel-sub">Segregate → weigh → QR scan → verified handover → coins</div></div>'+pill(f.status)+'</div><div class="waste-bars"><div class="waste-line"><span class="category-label"><i class="cat-dot"></i>Wet</span><span class="bar"><i style="width:72%"></i></span><strong>'+f.today.wet.toFixed(1)+' kg</strong></div><div class="waste-line"><span class="category-label"><i class="cat-dot" style="background:#85b6cb"></i>Dry</span><span class="bar"><i style="width:51%"></i></span><strong>'+f.today.dry.toFixed(1)+' kg</strong></div><div class="waste-line"><span class="category-label"><i class="cat-dot" style="background:#d6a667"></i>Special</span><span class="bar"><i style="width:18%"></i></span><strong>'+f.today.special.toFixed(1)+' kg</strong></div></div><div class="notice" style="margin-top:15px">Coins reward clean segregation and consistency, not waste quantity. Keep contamination low to protect your score.</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Sustainability badges</div><div class="panel-sub">Achievements earned through verified daily habits</div></div></div><div class="button-row"><span class="status-pill">♻ Clean Start</span><span class="status-pill">🌱 '+(f.score>=90?'Zero Contamination':'Consistent Sorter')+'</span><span class="status-pill">🔥 '+(f.streak>=14?'14-Day Streak':'Weekly Habit')+'</span></div></section></div></div>'}
function familyHistory(){let f=fam(),h=[...f.history,...state.collections.filter(c=>c.id===f.id)];return head('Collection history','Verified weights, segregation outcomes & points earned','<button class="btn" data-action="export">↓ Download history</button>')+'<div class="stats-grid">'+stat('This month','28 pickups','↑ 2|vs. last month','♻')+stat('Total material','112.4 kg','All categories|verified','⚖')+stat('Avg. clean score',f.score+'%','↑ 4%|this month','◉')+stat('Coins earned','+340','This month|quality based','◈')+'</div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Pickup & weight history</div><div class="panel-sub">Scale verification tolerance ±150 g</div></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date & time</th><th>Wet</th><th>Dry</th><th>Special</th><th>Verified total</th><th>Segregation</th><th>Clean coins</th></tr></thead><tbody>'+h.map((x,i)=>'<tr><td><b>'+x.date+'</b></td><td>'+x.wet+' kg</td><td>'+x.dry+' kg</td><td>'+x.special+' kg</td><td><b>'+(Number(x.wet)+Number(x.dry)+Number(x.special)).toFixed(1)+' kg</b></td><td>'+pill(x.quality)+'</td><td>◈ '+(i===0?'18':'14')+'</td></tr>').join('')+'</tbody></table></div></section>'}
function marketplace(){let f=fam(),cap=f.score>=90?.5:f.score>=80?.35:f.score>=70?.25:.15;return head('Good choices, made circular','Rewards made from recovered materials. Spend coins earned through clean sorting.','<span class="coin-balance">◈ '+fmt(f.coins)+' Clean coins</span>')+'<div class="notice" style="margin-bottom:14px"><b>Your Clean Score is '+f.score+'.</b> Redeem up to '+Math.round(cap*100)+'% of product price in coins. Pay the remainder at checkout. A better score unlocks a bigger coin contribution.</div><div class="market-grid">'+PRODUCTS.map(p=>{let max=Math.min(p.coins,Math.floor(p.price*cap),f.coins);return '<article class="product-card"><div class="product-art">'+p.icon+'</div><h3>'+p.name+'</h3><p>'+p.material+'</p><div class="product-meta"><span class="price">₹'+p.price+' <small>· max ◈ '+max+'</small></span><button class="btn btn-primary" data-action="redeem" data-product="'+p.id+'" '+(max<=0?'disabled':'')+'>Redeem</button></div><div class="panel-sub" style="margin-top:8px">Up to '+max+' coins · Pay ₹'+(p.price-max)+' · '+p.stock+' available</div></article>'}).join('')+'</div><section class="panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Your redeemed products</div><div class="panel-sub">Orders that close the waste-to-product loop</div></div></div>'+(f.redeemed.length?'<div class="table-scroll"><table class="data-table"><thead><tr><th>Product</th><th>Order</th><th>Coins used</th><th>Paid</th><th>Status</th></tr></thead><tbody>'+f.redeemed.map(r=>'<tr><td><b>'+r.name+'</b></td><td>'+r.order+'</td><td>◈ '+r.coins+'</td><td>₹'+r.paid+'</td><td>'+pill('Processing')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Your redeemed products will appear here.</div>')+'</section>'}
function leaderboard(){let rank=state.families.slice().sort((a,b)=>b.score-a.score||b.streak-a.streak);return head('Your community, greener together','Area leaderboard · clean score rewards quality, consistency & low contamination','<select class="select"><option>This week</option><option>This month</option></select>')+'<div class="overview-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">'+fam().area+' · top households</div><div class="panel-sub">You are ranked #'+(rank.findIndex(f=>f.id===fam().id)+1)+' in your community</div></div><span class="status-pill">This week</span></div>'+rank.slice(0,8).map((f,i)=>'<div class="leader-row"><span class="leader-rank">'+(i<3?['🥇','🥈','🥉'][i]:'#'+(i+1))+'</span><span><b>'+f.name+(f.id===fam().id?' · You':'')+'</b><small>'+f.area+' · '+f.streak+' day streak</small></span><span class="leader-score">'+f.score+' pts</span></div>').join('')+'</section><section class="panel"><div class="panel-head"><div><div class="panel-title">Your next milestone</div><div class="panel-sub">Keep your sorting streak alive</div></div></div><div class="score-hero" style="display:block"><div class="eyebrow" style="color:#c1e58a">UP NEXT · 30 DAY STREAK</div><h2>'+fam().streak+' / 30 days</h2><div class="bar" style="width:100%;height:7px;margin:14px 0"><i style="width:'+Math.min(fam().streak/30*100,100)+'%;background:#c9ee74"></i></div><p>Show up consistently. Clean habits earn more than extra weight.</p></div><div class="notice" style="margin-top:12px">Top 3 households earn the <b>Green Neighbour</b> badge and bonus Clean coins.</div></section></div>'}
function notifications(){return head('Notifications','Collection reminders, score updates & neighbourhood sustainability news','<button class="btn" data-action="mark-read">✓ Mark all read</button>')+'<section class="panel"><div class="notice-list">'+[['♻','Collection verified · Clean coins added','Your latest pickup was verified. +18 Clean coins earned. Today, 8:42 AM'],['◷','Collection reminder','Keep wet, dry and special waste separate for tomorrow’s pickup at 8:30 AM.'],['🌱','Neighbourhood milestone',fam().area+' improved its segregation score by 2.1% this week.'],['◈','New circular rewards added','Explore recycled stationery and reusable home essentials in the marketplace.']].map(x=>'<div class="notice-row"><span class="notice-icon">'+x[0]+'</span><span><b>'+x[1]+'</b><small>'+x[2]+'</small></span></div>').join('')+'</div></section>'}
function driverHome(){let list=state.families.filter(f=>f.route==='DW-04'||f.status==='On route'||f.status==='Pending').slice(0,7);return head('Good morning, Rajesh','Route DW-04 · Dwarka Sector 12 · Shift 7:30 AM – 2:00 PM','<span class="status-pill">● On shift</span><button class="btn btn-primary" data-page="scan">⌗ Scan family QR</button>')+'<div class="stats-grid">'+stat('Assigned stops','28','Route DW-04|today','⌖')+stat('Completed',String(12+state.collections.length),'↑ 4|ahead of schedule','✓')+stat('Remaining',String(Math.max(0,16-state.collections.length)),'6.4 km|route left','◷')+stat('Exceptions','1','Missed pickup|reported','⚑',false)+'</div><div class="driver-layout"><section class="panel"><div class="panel-head"><div><div class="panel-title">Today’s assigned route</div><div class="panel-sub">Optimized collection order · Dwarka Sector 12</div></div><button class="text-link" data-page="driver-summary">Full summary</button></div>'+list.map((f,i)=>'<div class="route-item"><span class="route-step">'+(i+1)+'</span><span><b>'+f.name+' · '+f.id+'</b><small>'+f.area+' · '+f.address+'</small></span><span class="route-status">'+f.status+'</span><button class="text-link" data-action="quick-scan" data-id="'+f.id+'">Scan</button></div>').join('')+'</section><div style="display:grid;gap:14px;align-content:start"><section class="panel"><div class="panel-head"><div><div class="panel-title">Collection checklist</div><div class="panel-sub">Verified handover sequence</div></div></div><div class="area-list">'+['Scan family QR','Verify waste categories','Enter vehicle scale weight','Confirm within ±150 g tolerance','Issue quality-based Clean coins'].map((x,i)=>'<div class="area-row"><span class="route-step">'+(i+1)+'</span><span><b>'+x+'</b></span><span class="route-status">'+(i<2?'Ready':'Next')+'</span></div>').join('')+'</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Vehicle scale</div><div class="panel-sub">Truck DL 1L AA 4821</div></div><span class="status-pill">Live</span></div><div class="score-hero"><div><div class="eyebrow" style="color:#c1e58a">CURRENT LOAD</div><h2>186.4 kg</h2></div><span style="font-size:25px">⚖</span></div></section></div></div>'}
function scanPage(){return head('Scan & verify','Scan household QR, inspect segregation and match declared weight to the vehicle scale','<span class="status-pill">⚖ Scale linked · ±150 g</span>')+'<div class="driver-layout"><section class="panel"><div class="panel-head"><div><div class="panel-title">Family QR scanner</div><div class="panel-sub">Use camera or enter unique family ID</div></div></div><div class="verify-form"><div class="button-row"><button class="btn btn-primary" data-action="camera-start">▣ Start camera scanner</button><button class="btn" data-action="camera-stop">Stop camera</button></div><video id="camera-feed" autoplay playsinline style="display:none;width:100%;max-height:250px;background:#142820;border-radius:12px"></video><div class="verify-result" id="camera-status">Camera QR detection requires browser support and permission. Manual family ID is always available.</div><label>Household family ID<select id="scan-family">'+state.families.map(f=>'<option value="'+f.id+'">'+f.name+' · '+f.id+' · '+f.area+'</option>').join('')+'</select></label><button class="btn btn-soft" data-action="load-family">Load household & declared weights</button><div id="verify-household"></div></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Transparent weight verification</div><div class="panel-sub">Confirmation unlocks only when scale totals match</div></div></div><div class="notice"><b>Required sequence</b><br>Family declares Wet + Dry + Special. Record vehicle scale readings. Match tolerance ±0.15 kg.</div><div class="waste-bars"><div class="waste-line"><span>Declared</span><span class="bar"><i style="width:78%"></i></span><strong id="declared-total">—</strong></div><div class="waste-line"><span>Vehicle</span><span class="bar"><i style="width:0%"></i></span><strong id="vehicle-total">—</strong></div></div><div id="verify-result" class="verify-result" style="margin-top:17px">Load a household to begin verification.</div></section></div>'}
function driverSummary(){return head('Daily collection summary','Driver Rajesh Kumar · Route DW-04 · 04 October 2026','<button class="btn" data-action="export">↓ Export shift report</button>')+'<div class="stats-grid">'+stat('Stops completed',(12+state.collections.length)+'/28','43%|route complete','✓')+stat('Verified weight','186.4 kg','Across|all categories','⚖')+stat('Clean handovers','92%','↑ 5%|vs. weekly average','◉')+stat('Missed / exception','1','Reported|with reason','⚑',false)+'</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Category weight summary</div><div class="panel-sub">Vehicle scale · verified household collections</div></div></div><div class="waste-bars"><div class="waste-line"><span>Wet</span><span class="bar"><i style="width:76%"></i></span><strong>98.2 kg</strong></div><div class="waste-line"><span>Dry</span><span class="bar"><i style="width:52%"></i></span><strong>72.6 kg</strong></div><div class="waste-line"><span>Special</span><span class="bar"><i style="width:17%"></i></span><strong>15.6 kg</strong></div></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Missed pickup / exception</div><div class="panel-sub">Submit reason for authority follow-up</div></div></div><label class="filter-box">Household<select id="missed-family">'+state.families.map(f=>'<option value="'+f.id+'">'+f.name+' · '+f.area+'</option>').join('')+'</select></label><label class="filter-box" style="margin-top:10px">Reason<select id="missed-reason"><option>Household unavailable</option><option>Access blocked</option><option>Vehicle scale issue</option><option>Contamination / unsafe material</option><option>Other operational issue</option></select></label><button class="btn btn-soft" style="margin-top:11px" data-action="report-missed">⚑ Submit exception report</button></section></div><section class="panel table-panel"><div class="panel-head"><div><div class="panel-title">Today’s completed handovers</div><div class="panel-sub">QR scan + scale match + confirmation</div></div></div>'+householdTable(state.families.filter(f=>f.status==='Collected'))+'</section>'}
function chain(){return processing()}
function body(){return ({overview, map:mapPage, families:familiesPage, performance, processing, 'collection-log':collectionLog,alerts,'family-home':familyHome,'family-history':familyHistory,marketplace,leaderboard,notifications,'driver-home':driverHome,scan:scanPage,'driver-summary':driverSummary,chain})[state.page]?.()||overview()}
function render(){if(map){map.remove();map=null}if(chart){chart.destroy();chart=null}clearTimeout(window.mapTimer);let labels={authority:'City authority',family:'Family portal',driver:'Collection driver',processor:'3R processor'};document.getElementById('app').innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">S</div><div><div class="brand-name">Saaf Saathi</div><div class="brand-sub">CIRCULAR CITIES, TOGETHER</div></div></div>'+nav[state.role].map(g=>'<div class="nav-caption">'+g[0]+'</div><div class="nav-list">'+g[1].map(i=>'<button class="nav-btn '+(state.page===i[0]?'active':'')+'" data-page="'+i[0]+'"><span class="nav-icon">'+i[1]+'</span><span>'+i[2]+'</span>'+(i[0]==='families'?'<span class="nav-count">12.8k</span>':'')+'</button>').join('')+'</div>').join('')+'<div class="sidebar-bottom"><div class="area-chip"><i class="pulse"></i><span><b>Delhi, India</b><small>Municipal network live</small></span></div><div class="user-mini"><div class="avatar">AO</div><div><b>Admin operator</b><small>Delhi command centre</small></div></div></div></aside><header class="topbar"><div class="crumb"><b>'+esc(names[state.page])+'</b> &nbsp;/&nbsp; '+(state.role==='authority'?'City overview':state.role==='family'?'Family account':state.role==='driver'?'Driver workspace':'Recovery network')+'</div><div class="top-actions"><span class="live-pill"><i class="live-dot"></i> LIVE DEMO</span><button class="icon-button" aria-label="Notifications" data-page="notifications">♧<i class="alert-dot"></i></button><div class="top-user"><span class="avatar">AO</span><div><b>Admin operator</b><small>'+labels[state.role]+'</small></div></div></div></header><main class="main"><div style="display:flex;gap:5px;margin:-4px 0 17px;flex-wrap:wrap"><span style="font-size:9px;color:#859189;align-self:center;margin-right:4px">VIEW AS</span>'+[['authority','Authority'],['family','Family'],['driver','Driver'],['processor','3R partner']].map(x=>'<button class="btn '+(state.role===x[0]?'btn-dark':'')+'" style="height:27px;font-size:9px;padding:0 10px" data-role="'+x[0]+'">'+x[1]+'</button>').join('')+'</div>'+body()+'</main></div>';initMap();initChart()}
function initMap(){let el=document.getElementById(state.page==='map'?'map-large':'map-overview');if(!el||!window.L)return;map=L.map(el,{scrollWheelZoom:false}).setView([28.6139,77.209],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);(state.sector==='All sectors'?AREAS:AREAS.filter(a=>a.name===state.sector)).forEach(a=>{let color=a.score>=88?'#48a46a':a.score>=78?'#e4a54b':'#d56759',icon=L.divIcon({className:'',html:'<div class="custom-marker" style="background:'+color+'"></div>',iconSize:[17,17],iconAnchor:[8,8]});L.marker([a.lat,a.lng],{icon}).addTo(map).bindPopup('<b>'+a.name+'</b><br>'+a.ward+'<br>Segregation <b>'+a.score+'%</b> · contamination '+a.contam+'%<br>'+fmt(a.families)+' households<br>7-day trend '+(a.trend>0?'+':'')+a.trend+'%');L.circle([a.lat,a.lng],{radius:700,color,weight:1,fillColor:color,fillOpacity:.08}).addTo(map)});setTimeout(()=>map&&map.invalidateSize(),150)}
function initChart(){let c=document.getElementById('performance-chart');if(!c||!window.Chart)return;chart=new Chart(c,{type:'line',data:{labels:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],datasets:[{label:'Segregation',data:[81,82,82,84,83,86,avg()],borderColor:'#32825b',backgroundColor:'#32825b18',fill:true,tension:.35,pointRadius:3,borderWidth:2},{label:'Contamination',data:[12,11,10,11,9,8,8],borderColor:'#d99a59',tension:.35,pointRadius:2,borderWidth:2}]},options:{maintainAspectRatio:false,responsive:true,plugins:{legend:{position:'bottom',labels:{boxWidth:8,usePointStyle:true,font:{size:9}}}},scales:{x:{grid:{display:false},ticks:{font:{size:9}}},y:{min:0,max:100,grid:{color:'#f0f2ef'},ticks:{font:{size:9}}}}}})}
function toast(s){document.querySelector('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.textContent=s;document.body.append(e);setTimeout(()=>e.remove(),3000)}
function modal(title,html){let d=document.createElement('div');d.className='modal-backdrop';d.innerHTML='<section class="modal"><div class="modal-head"><h2>'+title+'</h2><button class="close-btn" data-action="close-modal">×</button></div>'+html+'</section>';d.onclick=e=>{if(e.target===d)d.remove()};document.body.append(d)}
function showQr(id){let f=state.families.find(x=>x.id===id);if(f)modal('Customized family QR','<div class="qr-preview"><img src="'+qr(f,420)+'"><h3>'+f.name+'</h3><div class="muted">'+f.id+' · '+f.address+'</div><p class="muted">Driver scans this unique code to load the collection record.</p><a class="btn btn-primary" href="'+qr(f,420)+'" download="'+f.id+'-qr.png">↓ Download QR</a></div>')}
function exportCsv(){let rows=[['Family','Family ID','Area','Address','Members','Clean score','Clean coins','Streak','Status'],...state.families.map(f=>[f.name,f.id,f.area,f.address,f.members,f.score,f.coins,f.streak,f.status])],blob=new Blob([rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='saaf-saathi-households.csv';a.click();URL.revokeObjectURL(a.href);toast('CSV report downloaded')}
function openFamily(id){state.selectedFamily=id;state.role='family';state.page='family-home';save();render()}
function loadFamily(){let f=state.families.find(x=>x.id===document.getElementById('scan-family')?.value);if(!f)return;let t=f.today.wet+f.today.dry+f.today.special;document.getElementById('verify-household').innerHTML='<div class="profile-facts" style="padding:12px;border:1px solid var(--line);border-radius:11px;margin-top:4px"><div class="fact"><span>Household</span><b>'+f.name+' · '+f.members+' members</b></div><div class="fact"><span>Address</span><b>'+f.address+'</b></div><div class="fact"><span>Declared wet / dry / special</span><b>'+f.today.wet+' / '+f.today.dry+' / '+f.today.special+' kg</b></div><div class="fact"><span>Declared total</span><b>'+t.toFixed(2)+' kg</b></div></div><div class="weight-grid" style="margin-top:11px"><label>Wet scale (kg)<input type="number" id="weight-wet" step="0.05" value="'+f.today.wet.toFixed(2)+'"></label><label>Dry scale (kg)<input type="number" id="weight-dry" step="0.05" value="'+f.today.dry.toFixed(2)+'"></label><label>Special scale (kg)<input type="number" id="weight-special" step="0.05" value="'+f.today.special.toFixed(2)+'"></label></div><label style="margin-top:10px">Contamination observed<select id="contamination"><option value="0">None · clean segregation</option><option value="1">Low · one item misplaced</option><option value="2">Moderate · mixed materials</option><option value="3">High · major contamination</option></select></label><div class="verify-result" id="verify-result-inline" style="margin-top:10px">Scale total '+t.toFixed(2)+' kg · matching declared weight.</div><button class="btn btn-primary" style="width:100%;margin-top:10px" data-action="check-weight">⚖ Verify vehicle weight</button><button class="btn btn-soft" style="width:100%;margin-top:8px" data-action="confirm-pickup" disabled>✓ Confirm handover & issue Clean coins</button>';document.getElementById('declared-total').textContent=t.toFixed(2)+' kg';document.getElementById('vehicle-total').textContent='—';document.getElementById('verify-result').textContent='Enter scale values and verify.'}
function checkWeight(){let f=state.families.find(x=>x.id===document.getElementById('scan-family')?.value);if(!f)return;let w=['wet','dry','special'].map(k=>Number(document.getElementById('weight-'+k).value)||0),vehicle=w.reduce((a,b)=>a+b,0),declared=f.today.wet+f.today.dry+f.today.special,diff=Math.abs(vehicle-declared),ok=diff<=.15,text=(ok?'MATCH ✓':'MISMATCH ⚠')+' · Declared '+declared.toFixed(2)+' kg · Vehicle '+vehicle.toFixed(2)+' kg · Difference '+diff.toFixed(2)+' kg '+(ok?'(within ±0.15 kg)':'(confirmation locked; re-weigh or report exception)');['verify-result','verify-result-inline'].forEach(id=>{let x=document.getElementById(id);if(x){x.textContent=text;x.className='verify-result '+(ok?'match':'mismatch')}});document.getElementById('vehicle-total').textContent=vehicle.toFixed(2)+' kg';let b=document.querySelector('[data-action="confirm-pickup"]');if(ok)b.removeAttribute('disabled');else b.setAttribute('disabled','');window.verified=ok?{id:f.id,w}:null}
function confirmPickup(){if(!window.verified)return toast('Weight mismatch: confirmation is locked');let f=state.families.find(x=>x.id===window.verified.id),w=window.verified.w,c=Number(document.getElementById('contamination').value)||0,Q=Math.max(.45,1-c*.15),C=f.streak>=7?1.2:1,S=1+Math.min(f.streak,14)*.025,D=c*3,points=Math.max(2,Math.round(10*Q*C*S-D));f.score=Math.max(30,Math.min(100,Math.round(f.score+(c===0?1:-c))));f.coins+=points;f.streak++;f.status='Collected';f.today={wet:w[0],dry:w[1],special:w[2]};let rec={id:f.id,family:f.name,area:f.area,wet:w[0],dry:w[1],special:w[2],total:w.reduce((a,b)=>a+b,0).toFixed(2),score:f.score,points,driver:'Rajesh K.',date:new Date().toLocaleString('en-IN',{hour:'2-digit',minute:'2-digit'})+' · Today',quality:c===0?'Excellent':c===1?'Good':'Contamination noted'};state.collections.unshift(rec);save();toast('Pickup confirmed · '+points+' Clean coins issued');state.role='driver';state.page='driver-home';render()}
function redeem(id){let f=fam(),p=PRODUCTS.find(x=>x.id===id),cap=f.score>=90?.5:f.score>=80?.35:f.score>=70?.25:.15,coins=Math.min(p.coins,Math.floor(p.price*cap),f.coins),paid=p.price-coins;if(!coins)return toast('Not enough Clean coins');modal('Confirm your reward','<div class="notice">Made from recovered materials · '+p.material+'</div><div class="profile-facts"><div class="fact"><span>Product</span><b>'+p.name+'</b></div><div class="fact"><span>Retail price</span><b>₹'+p.price+'</b></div><div class="fact"><span>Score-based coin cap</span><b>'+Math.round(cap*100)+'% · ◈ '+coins+'</b></div><div class="fact"><span>Pay at checkout</span><b>₹'+paid+'</b></div><div class="fact"><span>Balance after redemption</span><b>◈ '+(f.coins-coins)+'</b></div></div><button class="btn btn-primary" style="width:100%;margin-top:16px" data-action="confirm-redeem" data-product="'+p.id+'" data-coins="'+coins+'" data-paid="'+paid+'">Confirm redemption</button>')}
function confirmRedeem(id,coins,paid){let f=fam(),p=PRODUCTS.find(x=>x.id===id);if(!p||f.coins<coins)return toast('Reward could not be redeemed');f.coins-=coins;f.redeemed.unshift({name:p.name,order:'SS-'+Date.now().toString().slice(-7),coins,paid});save();document.querySelector('.modal-backdrop')?.remove();render();toast('Reward redeemed · order '+f.redeemed[0].order)}
function addHousehold(){modal('Register a household','<div class="verify-form"><label>Family name<input id="new-name" placeholder="e.g. Rao Family"></label><label>Residential address<input id="new-address" placeholder="House, block, sector, Delhi PIN"></label><label>Area<select id="new-area">'+AREAS.map(a=>'<option>'+a.name+'</option>').join('')+'</select></label><label>Household members<input id="new-members" type="number" min="1" value="4"></label><button class="btn btn-primary" data-action="save-household">Create family ID & customized QR</button></div>')}
function saveHousehold(){let n=document.getElementById('new-name').value.trim(),addr=document.getElementById('new-address').value.trim(),a=document.getElementById('new-area').value;if(!n||!addr)return toast('Enter family name and full address');let f={id:'SS-'+a.slice(0,2).toUpperCase()+'-'+Math.floor(1000+Math.random()*8999),name:n.endsWith('Family')?n:n+' Family',area:a,address:addr,members:Number(document.getElementById('new-members').value)||1,score:75,coins:0,streak:0,status:'Pending',route:'DL-01',today:{wet:0,dry:0,special:0},history:[],redeemed:[]};state.families.unshift(f);state.selectedFamily=f.id;save();document.querySelector('.modal-backdrop')?.remove();state.page='families';state.role='authority';render();toast('Household registered · '+f.id+' QR created')}
function addProcessor(){modal('Record a processor receipt','<div class="verify-form"><label>Registered 3R dealer<input id="proc-name" placeholder="Processor / dealer name"></label><label>Material category<select id="proc-material"><option>Dry recyclables</option><option>Wet organics</option><option>Textile</option><option>E-waste</option><option>Plastic</option><option>Paper</option></select></label><div class="weight-grid"><label>Received kg<input id="proc-in" type="number" min="0" step=".1"></label><label>Recycled kg<input id="proc-recycle" type="number" min="0" step=".1" value="0"></label><label>Reused kg<input id="proc-reuse" type="number" min="0" step=".1" value="0"></label></div><div class="weight-grid"><label>Recovered kg<input id="proc-recover" type="number" min="0" step=".1" value="0"></label><label>Rejected kg<input id="proc-reject" type="number" min="0" step=".1" value="0"></label><label>Receipt ID<input id="proc-id" placeholder="Auto generated"></label></div><label>Processing date<input id="proc-date" type="date" value="'+new Date().toISOString().slice(0,10)+'"></label><button class="btn btn-primary" data-action="save-processor">Save verified batch receipt</button></div>')}
function saveProcessor(){let received=Number(document.getElementById('proc-in').value),processor=document.getElementById('proc-name').value.trim();if(!received||!processor)return toast('Enter dealer name and received weight');let r=Number(document.getElementById('proc-recycle').value)||0,u=Number(document.getElementById('proc-reuse').value)||0,v=Number(document.getElementById('proc-recover').value)||0,j=Number(document.getElementById('proc-reject').value)||0;if(r+u+v+j>received+.01)return toast('Outcome weights cannot exceed received weight');state.events.unshift({type:'processor',id:document.getElementById('proc-id').value||'PR-DEL-'+Date.now().toString().slice(-4),date:document.getElementById('proc-date').value,processor,material:document.getElementById('proc-material').value,received:received+' kg',recycled:r+' kg',reused:(u+v)+' kg',reject:j+' kg'});save();document.querySelector('.modal-backdrop')?.remove();render();toast('Processor receipt saved to 3R ledger')}
function quickScan(id){state.role='driver';state.page='scan';render();setTimeout(()=>{let s=document.getElementById('scan-family');s.value=id;loadFamily()},0)}
async function startCamera(){let msg=document.getElementById('camera-status'),video=document.getElementById('camera-feed');if(!('BarcodeDetector'in window)){msg.textContent='QR detector is unavailable in this browser. Select a family ID manually or use a compatible device.';return}try{camera=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=camera;video.style.display='block';let detector=new BarcodeDetector({formats:['qr_code']}),canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');msg.textContent='Camera active · point at a family QR.';scanTimer=setInterval(async()=>{if(video.readyState<2)return;canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0);let codes=await detector.detect(canvas);if(codes.length)try{let p=JSON.parse(codes[0].rawValue);if(p.family_id){document.getElementById('scan-family').value=p.family_id;stopCamera();msg.textContent='QR recognized · '+p.family_id;loadFamily()}}catch{}},500)}catch{msg.textContent='Camera permission unavailable. Enter the family ID manually.'}}
function stopCamera(){clearInterval(scanTimer);if(camera)camera.getTracks().forEach(t=>t.stop());camera=null;let v=document.getElementById('camera-feed');if(v)v.style.display='none'}
function reportMissed(){let f=state.families.find(x=>x.id===document.getElementById('missed-family').value),reason=document.getElementById('missed-reason').value;if(f)f.status='Missed';state.events.unshift({type:'exception',id:f?.id,family:f?.name,reason,date:new Date().toLocaleString()});save();render();toast('Missed pickup reported to authority')}
function bind(){document.addEventListener('click',e=>{let role=e.target.closest('[data-role]');if(role){state.role=role.dataset.role;state.page={authority:'overview',family:'family-home',driver:'driver-home',processor:'processing'}[state.role];save();render();return}let pg=e.target.closest('[data-page]');if(pg){go(pg.dataset.page);return}let b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'show-qr':showQr(b.dataset.id);break;case'family-detail':openFamily(b.dataset.id);break;case'export':exportCsv();break;case'close-modal':document.querySelector('.modal-backdrop')?.remove();break;case'add-household':addHousehold();break;case'save-household':saveHousehold();break;case'load-family':loadFamily();break;case'check-weight':checkWeight();break;case'confirm-pickup':confirmPickup();break;case'quick-scan':quickScan(b.dataset.id);break;case'camera-start':startCamera();break;case'camera-stop':stopCamera();break;case'redeem':redeem(b.dataset.product);break;case'confirm-redeem':confirmRedeem(b.dataset.product,Number(b.dataset.coins),Number(b.dataset.paid));break;case'add-processor':addProcessor();break;case'save-processor':saveProcessor();break;case'report-missed':reportMissed();break;case'mark-read':toast('All notifications marked as read');break;case'focus-area':modal('Plan an area intervention','<div class="notice"><b>'+b.dataset.area+'</b> · Run a 7-day door-to-door segregation drive, audit collection quality, and review contamination after the next route cycle.</div>');break;case'campaign':modal('Create awareness drive','<div class="verify-form"><label>Target area<select id="campaign-area">'+AREAS.map(a=>'<option>'+a.name+'</option>').join('')+'</select></label><label>Campaign focus<select><option>Wet / dry segregation</option><option>Reduce contamination</option><option>Special waste handling</option></select></label><label>Duration<select><option>7 days</option><option>14 days</option><option>30 days</option></select></label><button class="btn btn-primary" data-action="save-campaign">Save campaign plan</button></div>');break;case'save-campaign':state.events.unshift({type:'campaign',area:document.getElementById('campaign-area').value,date:new Date().toLocaleDateString()});save();document.querySelector('.modal-backdrop')?.remove();toast('Awareness drive added to area action plan')}});document.addEventListener('change',e=>{if(e.target.dataset.action==='select-family'){state.selectedFamily=e.target.value;save();render()}if(e.target.dataset.action==='sector-filter'){state.sector=e.target.value;save();render()}if(e.target.dataset.action==='period')toast('Report period updated to last '+e.target.value+' days');if(e.target.dataset.action==='family-area-filter')filterDirectory(e.target.value)});document.addEventListener('input',e=>{if(e.target.dataset.filter==='directory')filterDirectory(e.target.value);if(e.target.dataset.filter==='families')filterTable(e.target.value)});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.modal-backdrop')?.remove()})}
function filterDirectory(q){document.querySelectorAll('.family-card').forEach(c=>c.style.display=(!q||c.textContent.toLowerCase().includes(q.toLowerCase()))?'':'none')}
function filterTable(q){document.querySelectorAll('.data-table tbody tr').forEach(r=>r.style.display=(!q||r.textContent.toLowerCase().includes(q.toLowerCase()))?'':'none')}
bind();render();